class P:
    def __init__(self, x):
        self.x = x

    def __repr__(self):
        return f"P({self.x})"

    def __eq__(self, other):
        return self.x == other.x

print(P(1), P(1) == P(1))

from dataclasses import dataclass

@dataclass(order=True)
class V:
    major: int
    minor: int = 0

print(V(1, 2) < V(1, 3), V(1))

def log(func):
    def wrapper(*args):
        print("call", func.__name__)
        return func(*args)
    return wrapper

@log
def add(a, b):
    return a + b

print(add(1, 2))

